		c.JSON(http.StatusOK, gin.H{
			"environment":  environment,
			"flag_key":     flagKey,
			"marker":       marker,
			"evaluated_at": timeutil.Format(at),
			"status":       string(status),
			"reason":       string(reason),
			"config":       configBody,
		})
	}
