package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"testing"
	"time"

	"github.com/luwa07832/feature-flag-service/internal/store"
)

type apiHarness struct {
	router http.Handler
	db     *store.Store
	clock  *testClock
}

type testClock struct{ t time.Time }

func (c *testClock) advance(to time.Time) { c.t = to }

func newHarness(t *testing.T) *apiHarness {
	t.Helper()
	clock := &testClock{t: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)}
	st, err := store.OpenWithClock(filepath.Join(t.TempDir(), "service.db"), func() time.Time {
		return clock.t
	})
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return &apiHarness{router: NewRouter(st), db: st, clock: clock}
}

func (h *apiHarness) do(t *testing.T, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != "" {
		reader = bytes.NewReader([]byte(body))
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, path, reader)
	if body != "" {
		req.Header.Set("Content-Type", "application/json")
	}
	rec := httptest.NewRecorder()
	h.router.ServeHTTP(rec, req)
	return rec
}

func (h *apiHarness) must(t *testing.T, method, path, body string) map[string]any {
	t.Helper()
	rec := h.do(t, method, path, body)
	if rec.Code < 200 || rec.Code > 299 {
		t.Fatalf("%s %s -> %d %s", method, path, rec.Code, rec.Body.String())
	}
	var out map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		t.Fatalf("decode: %v: %s", err, rec.Body.String())
	}
	return out
}

func (h *apiHarness) createEnv(t *testing.T, key string) {
	t.Helper()
	h.must(t, http.MethodPost, "/api/v1/environments", `{"key":"`+key+`"}`)
}

func (h *apiHarness) createFlag(t *testing.T, key string) {
	t.Helper()
	h.must(t, http.MethodPost, "/api/v1/flags", `{"key":"`+key+`"}`)
}

func (h *apiHarness) putConfig(t *testing.T, env, flag, payload string) map[string]any {
	t.Helper()
	return h.must(t, http.MethodPut, "/api/v1/environments/"+env+"/flags/"+flag+"/config", payload)
}

func (h *apiHarness) setTime(ts string) {
	parsed, err := time.Parse(time.RFC3339Nano, ts)
	if err != nil {
		panic(err)
	}
	h.clock.advance(parsed)
}

func decodeBody(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var out map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		t.Fatalf("decode: %v: %s", err, rec.Body.String())
	}
	return out
}

func asMap(t *testing.T, v any) map[string]any {
// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"sync/atomic"
	"time"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db  *sql.DB
	now func() time.Time
	// versionSeq disambiguates configuration versions created within the same
	// nanosecond. Configuration history is append-only.
	versionSeq atomic.Uint64
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	return OpenWithClock(path, time.Now)
}

// OpenWithClock is Open with an injectable clock; production uses Open and
// deterministic tests use this entry point.
func OpenWithClock(path string, now func() time.Time) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	if now == nil {
		now = time.Now
	}
	return &Store{db: db, now: now}, nil
}

// Now returns the current time in the service's unified Unix-nanosecond
// representation.
func (s *Store) Now() int64 { return s.now().UnixNano() }

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// ErrNotFound reports a lookup that matched nothing.
var ErrNotFound = errors.New("not found")

// ErrAlreadyExists reports a create request for an existing key.
var ErrAlreadyExists = errors.New("already exists")

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS environments (
	key        TEXT PRIMARY KEY,
	created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS flags (
	key        TEXT PRIMARY KEY,
	created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS config_history (
	id          INTEGER PRIMARY KEY AUTOINCREMENT,
	flag_key    TEXT NOT NULL,
	environment TEXT NOT NULL,
	version     TEXT NOT NULL UNIQUE,
	enabled     INTEGER NOT NULL,
	percentage  INTEGER NOT NULL,
	starts_at   INTEGER,
	ends_at     INTEGER,
	changed_at  INTEGER NOT NULL,
	tombstone   INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_config_env_time
	ON config_history(environment, changed_at, id);
CREATE INDEX IF NOT EXISTS idx_config_flag_env_time
	ON config_history(flag_key, environment, changed_at, id);
`

